mkdir -p /private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/1f1355de-28df-4625-a275-2807a4d24325/scratchpad && cat > /private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/1f1355de-28df-4625-a275-2807a4d24325/scratchpad/semantic-probe.mjs <<'EOF'
const QUERIES = ["experiment", "hypothesis about memory", "evidence"];

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamAlphaAPI?.data?.async));
  },

  async run({ page }) {
    return page.evaluate(async (queries) => {
      const api = window.roamAlphaAPI;
      const enabled = (() => {
        try {
          return api.data.semanticSearchEnabled();
        } catch (e) {
          return `threw: ${String(e)}`;
        }
      })();

      const out = { semanticSearchEnabled: enabled, queries: {} };
      if (enabled !== true) return out;

      for (const q of queries) {
        try {
          const hits = await api.data.async.semanticSearch({
            "search-str": q,
            "hide-code-blocks": false,
            "search-blocks": false,
            "search-pages": true,
            k: 30,
          });
          const pages = hits.filter((h) => h.type === "page");
          const scores = pages.map((h) => h.score);
          const sortedDesc = [...scores].sort((a, b) => b - a);
          out.queries[q] = {
            hitCount: hits.length,
            pageCount: pages.length,
            scores,
            returnedOrderIsScoreDesc:
              JSON.stringify(scores) === JSON.stringify(sortedDesc),
            first: pages.slice(0, 10).map((h) => ({
              uid: h.uid,
              score: h.score,
              title: h.title || h.text || h.string || null,
            })),
          };
        } catch (e) {
          out.queries[q] = { error: String(e) };
        }
      }
      return out;
    }, queries);
  },
};
const queries = QUERIES;
EOF
